        return grid

    bg = grid[0][0] if grid else 0
    h, w = len(grid), len(grid[0])
    result = [[bg] * w for _ in range(h)]

    # Collect positions by value
    value_positions = {v: [] for v in range(1, 10)}

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != bg and 1 <= val <= 9:
                value_positions[val].append((r, c))

    # Direction mappings based on demonstrated patterns
    # Odd values 1,3: extend diagonally FULL in both directions (UP-LEFT and DOWN-RIGHT)
    # Even values 6,8: extend DOWN-RIGHT only (like large evens in demo)

    for val, positions in value_positions.items():
        if val == 1 or val == 3:
            # Odd values extend in both diagonal directions along the line
            for r, c in positions:
                # UP-LEFT direction (-1, -1)
                i, j = r, c
                while i >= 0 and j >= 0:
                    result[i][j] = val
                    i -= 1
                    j -= 1

                # DOWN-RIGHT direction (1, 1)
                i, j = r, c
                while i < h and j < w:
                    result[i][j] = val
                    i += 1
                    j += 1
        else:  # Even values (including 6, 8)
            # Extend DOWN-RIGHT
            for r, c in positions:
                i, j = r, c
                while i < h and j < w:
                    result[i][j] = val
                    i += 1
                    j += 1

    return result
